    '''CREATE TABLE saving_goals(id TEXT PRIMARY KEY, name TEXT NOT NULL, target_satang INTEGER NOT NULL CHECK(target_satang > 0), monthly_target_satang INTEGER NOT NULL CHECK(monthly_target_satang >= 0), backing_account_id TEXT REFERENCES accounts(id), is_emergency_fund INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, sync_status TEXT NOT NULL DEFAULT 'local', user_id TEXT)''',
